// Specification for the parse_music function
method parse_music(music_string: string) returns (result: seq<int>)
    requires music_string != null
    // Precondition: music_string must not be null
    ensures |result| > 0 ==> 
        // Postcondition: if result is not empty, it contains only integers corresponding to the beats of the notes
        forall i :: 0 <= i < |result| ==> 
            result[i] == 4 || result[i] == 2 || result[i] == 1
    ensures |result| == CountNotes(music_string)
    // Postcondition: the length of the result corresponds to the number of valid notes parsed from the input string

// Auxiliary function to count notes in the music_string
function CountNotes(music_string: string): int
    requires music_string != null
    ensures CountNotes(music_string) >= 0
    decreases |music_string|
{
    if |music_string| == 0 then
        return 0
    else if music_string.StartsWith("o ") then
        return 1 + CountNotes(music_string[2..])
    else if music_string.StartsWith("o| ") then
        return 1 + CountNotes(music_string[3..])
    else if music_string.StartsWith(".| ") then
        return 1 + CountNotes(music_string[3..])
    else if music_string.StartsWith(" ") then
        return CountNotes(music_string[1..])
    else
        return CountNotes(music_string[1..])
}
